/// <summary>
/// Collects the objects a populate (index) job had to skip because reading their metadata failed.
/// Writes the first few as warnings and a summary at the end, so one bad object no longer
/// stops the whole run and the infolog is not flooded.
/// </summary>
public final class ARBAOTPopulateLog
{
    const int MaxWarnings = 20;
    int skippedCount;
}

Method.Source:
/// <summary>
/// Creates a new log.
/// </summary>
/// <returns>A new <c>ARBAOTPopulateLog</c> instance.</returns>
public static ARBAOTPopulateLog construct()
{
    return new ARBAOTPopulateLog();
}

/// <summary>
/// Records an object that was skipped. Call from the catch block of the per-object processing.
/// </summary>
/// <param name="_objectKind">The kind of object, for example Form or Table.</param>
/// <param name="_objectName">The object name.</param>
public void skip(str _objectKind, str _objectName)
{
    skippedCount++;

    if (skippedCount <= MaxWarnings)
    {
        str reason = ARBAOTBrowserHelper::lastClrErrorText();
        warning(strFmt("@AOTBrowser:PopulateObjectSkipped", _objectKind, _objectName, reason));
    }
}

/// <summary>
/// Gets the number of skipped objects.
/// </summary>
/// <returns>The number of skipped objects.</returns>
public int skippedCount()
{
    return skippedCount;
}

/// <summary>
/// Writes a summary line when objects were skipped.
/// </summary>
public void summary()
{
    if (skippedCount)
    {
        warning(strFmt("@AOTBrowser:PopulateObjectsSkippedSummary", skippedCount));
    }
}
